#include <iostream>
#include <string>
#include <memory>
using namespace std;

class Order {
public:
    string id;
    Order(string id) : id(id) {}
};

class NotificationSender {
public:
    virtual void send(const Order& order) = 0;
    virtual ~NotificationSender() {}
};

class EmailSender : public NotificationSender {
public:
    void send(const Order& order) override {
        cout << "Emailing order confirmation for " << order.id << endl;
    }
};

class SmsSender : public NotificationSender {
public:
    void send(const Order& order) override {
        cout << "Texting order confirmation for " << order.id << endl;
    }
};

class OrderNotifier {
private:
    shared_ptr<NotificationSender> sender;
public:
    OrderNotifier(shared_ptr<NotificationSender> sender) : sender(sender) {}
    void notify(const Order& order) {
        sender->send(order);
    }
};

int main() {
    OrderNotifier notifier(make_shared<SmsSender>());
    notifier.notify(Order("ORD-42"));
    return 0;
}

