interface ConfigLoader {
    Config load(String raw);
}

class JsonConfigLoader implements ConfigLoader {
    public Config load(String raw) {
        return Config.fromJson(raw);
    }
}

class YamlConfigLoader implements ConfigLoader {
    public Config load(String raw) {
        return Config.fromYaml(raw);
    }
}

class ConfigLoaderFactory {
    static ConfigLoader create(String format) {
        switch (format) {
            case "json": return new JsonConfigLoader();
            case "yaml": return new YamlConfigLoader();
            default: throw new IllegalArgumentException("Unsupported format: " + format);
        }
    }
}

ConfigLoader loader = ConfigLoaderFactory.create("json");
Config config = loader.load("{\"port\": 8080}");

