#include <iostream>
#include <string>
#include <memory>
#include <stdexcept>
using namespace std;

class Config {
public:
    int port;
    static Config fromJson(const string& raw) {
        Config c;
        c.port = 8080;
        return c;
    }
    static Config fromYaml(const string& raw) {
        Config c;
        c.port = 8080;
        return c;
    }
};

class ConfigLoader {
public:
    virtual Config load(const string& raw) = 0;
    virtual ~ConfigLoader() {}
};

class JsonConfigLoader : public ConfigLoader {
public:
    Config load(const string& raw) override {
        return Config::fromJson(raw);
    }
};

class YamlConfigLoader : public ConfigLoader {
public:
    Config load(const string& raw) override {
        return Config::fromYaml(raw);
    }
};

class ConfigLoaderFactory {
public:
    static shared_ptr<ConfigLoader> create(const string& format) {
        if (format == "json") return make_shared<JsonConfigLoader>();
        if (format == "yaml") return make_shared<YamlConfigLoader>();
        throw invalid_argument("Unsupported format: " + format);
    }
};

int main() {
    auto loader = ConfigLoaderFactory::create("json");
    Config config = loader->load("{\"port\": 8080}");
    cout << config.port << endl;
    return 0;
}
